using UnityEngine;using UnityEditor;
public static class DungeonDecorationMainSetup {
 public static string Apply(){var map=DungeonMapSettings.Current;var regions=map.regions!=null?map.regions:DungeonRegionSettings.Current;const string path="Assets/Resources/Decorations/MainDungeonDecorations.asset";var settings=AssetDatabase.LoadAssetAtPath<DungeonDecorationSettings>(path);if(settings==null){settings=ScriptableObject.CreateInstance<DungeonDecorationSettings>();settings.catalog=DungeonDecorationCatalog.Current;settings.regions=regions;settings.automaticEnabled=true;settings.maximumAutomatic=60;settings.minimumSpacing=3;settings.seed=1987;foreach(var r in regions.regions)settings.zones.Add(new DecorationZoneRule{zoneId=r.id,enabled=true,density=r.safeArea?.12f:.20f,theme=r.safeArea?DecorationTheme.Safe:r.id=="zone-2"?DecorationTheme.Corrupt:DecorationTheme.General});AssetDatabase.CreateAsset(settings,path);}Undo.RecordObject(map,"Asignar ambientación del dungeon");map.decorations=settings;EditorUtility.SetDirty(map);EditorUtility.SetDirty(settings);AssetDatabase.SaveAssets();return DungeonDecorationPlanner.Build(map).Count+" decoraciones automáticas estables; máximo60, sin alterar casillas ni entidades";}
}
